section.sourcecode:
// 入力パラメーター
MAX_RATE;          // 設定された最大持続レート [b/s]
QPROTECT_ON;       // キュー保護が有効 [デフォルト: TRUE]
CRITICALqL_us;     // LL キューのしきい値遅延 [µs] デフォルト: MAXTH_us
CRITICALqLSCORE_us;// しきい値キューイングスコア [デフォルト: 4000 µs]
LG_AGING;          // キューイングスコアの減衰率 [デフォルト: 19]
                   //   輻輳レートの 2 を底とする対数 [lg(B/s)]

// calcProbNative() アルゴリズムの入力パラメーター:
MAXTH_us;          // LL AQM の最大マーキングしきい値 [デフォルト: 1000 µs]
LG_RANGE;          // ランプの範囲の 2 を底とする対数 [lg(ns)]
                   //   デフォルト: 2^19 = 524288 ns（約 525 µs）

// 定数（入力パラメーターから導出するか、ハードコードする）
T_RES;                                    // t_exp の分解能 [ns]
                                          // 単位を変換（近似）
AGING = pow(2, (LG_AGING-30) ) * T_RES;   // lg([B/s]) から [B/T_RES] へ
CRITICALqL = CRITICALqL_us * 1000;        // [µs] から [ns] へ
CRITICALqLSCORE = CRITICALqLSCORE_us * 1000/T_RES; // [µs] から [T_RES] へ
// キューイングスコアの条件のしきい値
CRITICALqLPRODUCT = CRITICALqL * CRITICALqLSCORE;
qLSCORE_MAX = 5E9 / T_RES;           // 最大キューイングスコア = 5 秒

ATTEMPTS = 2; // バケットを選ぶ最大試行回数（ベンダー固有）
BI_SIZE = 5;  // 非デフォルトのバケットのインデックス番号のビット幅
NBUCKETS = pow(2, BI_SIZE);  // 非デフォルトのバケットの数
MASK = NBUCKETS-1;     // BI_SIZE 個の LSB が立った便利な定数

                       // キュー保護の終了状態
EXIT_SUCCESS  = 0;     // パケットを転送する
EXIT_SANCTION = 1;     // パケットをリダイレクトする

MAX_PROB      = 1; // 整数演算では、オーバーフローの余地を
                   //   残すために大きな整数（例: 2^31）を使う
MAXTH = MAXTH_us * 1000;   // 最大マーキングしきい値 [ns]
MAX_FRAME_SIZE = 2000;  // DOCSIS 全体の定数 [B]
// 低速リンクのための 2 MTU の最小マーキングしきい値 [ns]
FLOOR =  2 * 8 * MAX_FRAME_SIZE * 10^9 / MAX_RATE;
RANGE = (1 << LG_RANGE);      // ランプの範囲 [ns]
MINTH = max ( MAXTH - RANGE, FLOOR);
MAXTH = MINTH + RANGE;           // 最大マーキングしきい値 [ns]

// 公開変数:
qdelay;        // LL キューの現在のキューイング遅延 [ns]
probNative;    // LL キューのネイティブマーキング確率（[0,1] の範囲）

// 外部変数
packet;            // パケットヘッダーのフィールドを保持する構造体
packet.size;       // 現在のパケットのサイズ [B]
packet.uflow;      // 現在のパケットのフロー識別子
                   //   （例: 5 タプル、IPsec の場合は 4 タプル）

// qdelay を返す DOCSIS の関数の無関係な詳細は省略
qdelayL(...)      // 低遅延キューの現在の遅延を返す [ns]

struct bucket { // フローごとの状態を保持するリーキーバケットの構造体
   id;          // バケットを使用するフローの識別子（例: 5 タプル）
   t_exp;       // T_RES 単位の有効期限
                // (t_exp - now) = フローの変換後のキューイングスコア
};
struct bucket buckets[NBUCKETS+1];

classifier(packet) {
   // ECN、DSCP、ローカル使用のフィールドを使ってキューを決定
   queue_id = classify(packet);
   //   LQ と CQ は classify() が返す有効なキュー ID のマクロ
   if (queue_id == LQ) {
      // パケットが低遅延サービスフローに分類された場合
      aqm_mark(packet); // AQM に基づき必要に応じて ECN マークを付ける
      if (QPROTECT_ON) {
         if (qprotect(packet, ...) == EXIT_SANCTION) {
            // パケットをクラシックサービスフローにリダイレクト
            queue_id = CQ;
         }
      }
   return queue_id;
}

// パケットごとのキュー保護
qprotect(packet, ...) {

   bckt_id;   // バケットのインデックス
   qLscore;   // パケットのフローの T_RES 単位のキューイングスコア

   qdelay = qL.qdelay(...);
   probNative = calcProbNative(qdelay);

   bckt_id = pick_bucket(packet.uflow);
   qLscore = fill_bucket(buckets[bckt_id], packet.size, probNative);

   // パケットに制裁を科すかどうかを決定
   if ( ( ( qdelay > CRITICALqL ) // qdelay がしきい値を超えるか確認...
      // ...かつ、qdelay/CRITICALqL でスケールしたフローの
      // ...キューイングスコアが CRITICALqLSCORE を超える
      && ( qdelay * qLscore > CRITICALqLPRODUCT ) )
      // または qLSCORE_MAX に到達
      || ( qLscore >= qLSCORE_MAX ) )

      return EXIT_SANCTION;

   else
      return EXIT_SUCCESS;
}

// フロー uflw に関連付けられたバケットを選ぶ
pick_bucket(uflw) {

   now;                      // 現在時刻
   j;                        // ループカウンター
   h32;                      // パケットのフロー ID のハッシュを保持
   h;                        // 確認中のバケットのインデックス
   hsav;                     // 暫定的に選んだバケットのインデックス

   h32   = hash32(uflw);     // フロー ID の 32 ビットハッシュ
   hsav  = NBUCKETS;         // デフォルトのバケット
   now   = get_time_now();   // T_RES 単位

   // for ループは、ATTEMPTS 個のバケットがフロー ID に所有されているか確認する
   // また、期限切れで再利用できるバケットがあれば、その最初の
   // バケットを記録する。
   // 所有権の確認がすべて終わるまでバケットを再利用してはならない
   for (j=0; j<ATTEMPTS; j++) {
      // 各試行でハッシュの下位 BI_SIZE ビットを使う
      h = h32 & MASK;
      if (buckets[h].id == uflw) {    // uflw のバケットが見つかったら...
         if (buckets[h].t_exp <= now) // ...バケットが期限切れなら...
            buckets[h].t_exp = now;   // ...リセットする
         return h;                    // いずれにせよ、それを使う
      }
      else if ( (hsav == NBUCKETS)  // 期限切れのバケットをまだ見ておらず
                                    //   このバケットが期限切れの場合
           && (buckets[h].t_exp <= now) ) {
         hsav = h;                  // それを暫定バケットに設定
      }
      h32 >>= BI_SIZE;          // 次の試行のためにハッシュをビットシフト
   }
   // ここに来たら、確認したどのバケットもそのフロー ID に所有されていない
   if (hsav != NBUCKETS) {
      // ここに来たら、上の for ループで期限切れのバケットを見つけた
      buckets[hsav].t_exp = now;              // 期限切れのバケットをリセット
   } else {
      // ここに来たら、デフォルトのバケット（残りかす）を使う必要がある
      if (buckets[hsav].t_exp <= now) {   // 残りかすが期限切れなら...
         buckets[hsav].t_exp = now;       // ...リセットする
      }
   }
   buckets[hsav].id = uflw; // どちらの場合も、再利用のために確保する
   return hsav;
}

fill_bucket(bckt_id, pkt_sz, probNative) {
   now;                                       // 現在時刻
   now = get_time_now();                      // T_RES 単位
   // パケットのキューイングスコアを加算
   // 整数演算では、除算をビットシフトで置き換えられる
   qLscore = min(buckets[bckt_id].t_exp - now
                 + probNative * pkt_sz / AGING, qLSCORE_MAX);
   buckets[bckt_id].t_exp = now + qLscore;
   return qLscore;
}

calcProbNative(qdelay){
      if ( qdelay >= MAXTH ) {
         probNative = MAX_PROB;
      } else if ( qdelay > MINTH ) {
         probNative = MAX_PROB * (qdelay - MINTH)/RANGE;
         // 実際には、* と / はビットシフトを使う
      } else {
         probNative = 0;
      }
      return probNative;
}

if (  ( qdelay > CRITICALqL )  // qdelay がしきい値を超えるか確認...
   // ...かつ、qdelay/CRITICALqL でスケールしたフローの
   // ...キューイングスコアが CRITICALqLSCORE を超える
   && ( qdelay * qLscore > CRITICALqLPRODUCT ) )
   // CRITICALqLPRODUCT = CRITICALqL * CRITICALqLSCORE であることに注意
